{
  "technical_and_design_decisions": [
    "For U1 (wiki migration): Store wiki content as Markdown files in a /docs directory within the project repository, using Git for versioning and the repository's native Markdown rendering for wiki display.",
    "For U2 (Hadoop namenode config): Introduce a dedicated spring.hadoop.namenode.address configuration property in XD's default config, with fallback to existing environment variable lookup if the property is unset.",
    "For U3 (jdbchdfs passthrough): Add a passthrough.mode boolean flag to the jdbchdfs batch module that disables chunk processing and uses direct stream read/write when enabled.",
    "For U4 (execution context decoupling): Implement the decoupled execution context fix in Spring Batch core first, then update XD's Batch module to use the new API, removing the existing XD-2486 workaround.",
    "For U5 (Java Config custom job modules): Extend XD's module deployment logic to scan for @Configuration annotated classes in uploaded job JARs, and fix the job existence check to validate full module deployment before allowing launch.",
    "For U6 (pluggable deployment SPI): Define a generic ModuleDeployment SPI that abstracts deployment target operations, with the Receptor API as the first concrete implementation, refactoring existing Lattice/Diego code to use the SPI.",
    "For U7 (module shortDescription): Add a mandatory shortDescription field to the XD module metadata schema, with validation to reject modules missing this field, and update all existing module documentation to include the field.",
    "For U8 (HDFS Python script hosting): Add a hdfs.script.base.path configuration property to the XD shell processor, with logic to fetch Python scripts from HDFS and cache them locally for subsequent runs."
  ],
  "assumptions": [
    "The development team has read/write access to all relevant codebases (Spring Batch, Spring XD, Hadoop integration modules) and associated issue trackers.",
    "Existing automated test suites for all affected modules are available and can be executed locally to validate changes without regressions.",
    "The Hadoop namenode address format is consistent across all target deployment environments, so a single configuration property is sufficient for all use cases.",
    "The Receptor API has stable, publicly documented interfaces that can be used to implement the pluggable deployment SPI without breaking changes.",
    "A compatible Python runtime is pre-installed on all target XD-on-Cloud Foundry instances, so no additional runtime provisioning is required for the shell processor functionality.",
    "The target project repository for wiki migration (U1) is already created and accessible to all development team members."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Export and clean existing wiki content",
      "activity_description": "Export all existing wiki content to Markdown format, fix broken links and formatting inconsistencies to prepare for migration to the project repo.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A2",
      "activity_name": "Set up project repo docs structure",
      "activity_description": "Create a /docs directory in the target project repository, add cleaned Markdown wiki files, and configure the repository to render Markdown content as a wiki.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A3",
      "activity_name": "Update internal wiki references",
      "activity_description": "Update all internal links, documentation references, and team onboarding materials to point to the new repository-based wiki location.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A4",
      "activity_name": "Add namenode config property to XD schema",
      "activity_description": "Add the spring.hadoop.namenode.address property to XD's default configuration schema and sample configuration files.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A5",
      "activity_name": "Modify Hadoop config loader logic",
      "activity_description": "Update the Hadoop configuration loader to prioritize the new spring.hadoop.namenode.address property, with fallback to the existing environment variable lookup if the property is not set.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A6",
      "activity_name": "Add tests for namenode config logic",
      "activity_description": "Create unit and integration tests for the new namenode configuration logic, covering scenarios where the property is set, unset with environment variable present, and both missing.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A7",
      "activity_name": "Add passthrough mode config to jdbchdfs module",
      "activity_description": "Add a passthrough.mode boolean configuration parameter to the jdbchdfs batch module definition to allow users to enable passthrough mode.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A8",
      "activity_name": "Implement jdbchdfs passthrough stream logic",
      "activity_description": "Implement direct HDFS stream read/write logic for passthrough mode, bypassing all chunk processing steps to eliminate batch read/write overhead.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A9",
      "activity_name": "Add tests for jdbchdfs passthrough mode",
      "activity_description": "Create unit and integration tests for passthrough mode, validating data integrity, correct error handling, and performance improvements over chunk mode.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A10",
      "activity_name": "Implement decoupled execution context API in Spring Batch",
      "activity_description": "Design and implement the decoupled execution context API in Spring Batch core, removing tight coupling between the execution context and job launch lifecycle to avoid classloader and serialization errors.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A11",
      "activity_name": "Add tests for new Spring Batch API",
      "activity_description": "Create unit tests for the new decoupled execution context API, covering context serialization, classloader isolation, and edge case error scenarios.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A12",
      "activity_name": "Refactor XD Batch module to use new API",
      "activity_description": "Refactor Spring XD's Batch module to use the new decoupled execution context API, removing the existing XD-2486 workaround code.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A13",
      "activity_name": "Run XD Batch integration tests for regression",
      "activity_description": "Execute the full suite of existing XD Batch integration tests to validate that the changes introduce no regressions in existing functionality.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A14",
      "activity_name": "Extend module deployment to support Java Config",
      "activity_description": "Update XD's module deployment logic to scan uploaded job module JARs for @Configuration annotated classes, in addition to the existing XML configuration scanning support.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A15",
      "activity_name": "Fix job existence check logic",
      "activity_description": "Fix the job existence validation logic to confirm the module is fully deployed before allowing job launch, and update error messaging to be clear for users.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A16",
      "activity_name": "Add tests for Java Config custom job modules",
      "activity_description": "Create unit and integration tests for Java Config based custom job modules, covering deployment, launch, and error case scenarios.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A17",
      "activity_name": "Define generic ModuleDeployment SPI",
      "activity_description": "Define the generic ModuleDeployment SPI interface, including required methods for module upload, deployment, lifecycle management, and status checks.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A18",
      "activity_name": "Implement Receptor API adapter for SPI",
      "activity_description": "Implement a Receptor API adapter that maps Receptor operations to the generic ModuleDeployment SPI methods, enabling Receptor as a supported deployment target.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A19",
      "activity_name": "Refactor Lattice/Diego code to use SPI",
      "activity_description": "Refactor existing Lattice and Diego deployment implementation code to use the new generic ModuleDeployment SPI, removing target-specific logic from core XD modules.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A20",
      "activity_name": "Add tests for SPI and Receptor adapter",
      "activity_description": "Create unit tests for the ModuleDeployment SPI and Receptor adapter, validating correct behavior for all supported deployment operations.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A21",
      "activity_name": "Update module metadata schema for shortDescription",
      "activity_description": "Update the XD module metadata schema to require a shortDescription field, and add validation logic to reject module uploads that are missing this field.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A22",
      "activity_name": "Audit and update existing module docs",
      "activity_description": "Audit all existing XD module documentation, add shortDescription entries to each module's documentation page to provide users with quick overviews of module functionality.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A23",
      "activity_name": "Add tests for shortDescription functionality",
      "activity_description": "Create unit tests to validate that shortDescription is present in all module metadata, passes validation, and is rendered correctly in generated documentation.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A24",
      "activity_name": "Add HDFS script path config to shell processor",
      "activity_description": "Add a hdfs.script.base.path configuration property to the XD shell processor's configuration schema to allow users to specify the HDFS path for Python scripts.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A25",
      "activity_name": "Implement HDFS script fetch and caching logic",
      "activity_description": "Implement logic in the shell processor to fetch Python scripts from the configured HDFS path, with local caching of fetched scripts to avoid repeated HDFS reads for subsequent executions.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "A26",
      "activity_name": "Add tests for HDFS script loading",
      "activity_description": "Create unit and integration tests for HDFS script loading, covering valid script fetch, missing script error handling, cache hit/miss scenarios, and permission errors.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 41
  }
}

